// never visible to another session.

const sessions = new Map(); // session_id -> Map(key -> value)

function isString(v) {
  return typeof v === 'string';
}

function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

// Validate arguments against a JSON-schema-like definition.
// Enforces: object shape, no extra properties, required fields, basic types.
function validateArgs(schema, args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }
  const props = schema.properties || {};
  for (const k of Object.keys(args)) {
    if (!(k in props)) {
      throw new Error(`unexpected argument: ${k}`);
    }
  }
  for (const r of schema.required || []) {
    if (!(r in args)) {
      throw new Error(`missing required argument: ${r}`);
    }
  }
  for (const [k, v] of Object.entries(args)) {
    const def = props[k];
    if (def.type === 'string' && typeof v !== 'string') {
      throw new Error(`${k} must be a string`);
    }
  }
}

const TOOLS = [
  {
    name: 'begin_session',
    description: 'Begin a new state-isolated session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
      },
      required: ['session_id'],
      additionalProperties: false,
    },
  },
  {
    name: 'put_value',
    description: 'Store a string value for a key within a session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' },
        value: { type: 'string' },
      },
      required: ['session_id', 'key', 'value'],
      additionalProperties: false,
    },
  },
  {
    name: 'get_value',
    description: 'Retrieve a stored value for a key within a session.',
    inputSchema: {
      type: 'object',
      properties: {
        session_id: { type: 'string' },
        key: { type: 'string' },
      },
      required: ['session_id', 'key'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS.map(({ name, description, inputSchema }) => ({
    name,
    description,
    inputSchema,
  }));
}

